#!/usr/bin/env python3\n\"\"\"\nOptimized settings for Mac Air M4 with 10-core CPU and 10-core GPU.\n\nThis configuration maximizes performance on Apple Silicon M4 architecture.\n\"\"\"\n\nimport os\nfrom typing import Dict, List\nfrom pydantic import BaseSettings\nfrom pathlib import Path\n\nclass M4Settings(BaseSettings):\n    \"\"\"\n    Optimized settings for Mac Air M4.\n    \n    Hardware Specs:\n    - Mac Air M4\n    - 10-core CPU\n    - 10-core GPU (Metal GPU)\n    - Up to 24GB unified memory\n    \"\"\"\n    \n    # ============================================================\n    # PROJECT PATHS\n    # ============================================================\n    PROJECT_ROOT = Path(__file__).parent.parent\n    DATA_DIR = PROJECT_ROOT / \"data\"\n    MODELS_DIR = PROJECT_ROOT / \"models\"\n    LOGS_DIR = PROJECT_ROOT / \"logs\"\n    \n    # ============================================================\n    # M4 GPU OPTIMIZATION\n    # ============================================================\n    # Use Apple Metal GPU for acceleration\n    DEVICE: str = \"mps\"  # Metal Performance Shaders (GPU acceleration)\n    # Fallback to \"cpu\" if GPU issues, or force with os.getenv(\"USE_CPU\", \"false\")\n    USE_UNIFIED_MEMORY: bool = True  # M4 has unified memory architecture\n    \n    # GPU Memory Management (M4 has shared memory with CPU)\n    GPU_BATCH_SIZE: int = 32  # Larger batches for GPU\n    CPU_BATCH_SIZE: int = 16  # Conservative for CPU fallback\n    MAX_GPU_MEMORY_MB: int = 8000  # Conservative allocation (M4 has up to 20GB+ shared)\n    \n    # ============================================================\n    # EMBEDDING OPTIMIZATION FOR M4\n    # ============================================================\n    # High-performance model for M4\n    EMBEDDING_MODEL: str = \"sentence-transformers/all-MiniLM-L6-v2\"\n    # Alternative faster model (if needed)\n    EMBEDDING_MODEL_FAST: str = \"sentence-transformers/paraphrase-MiniLM-L6-v2\"\n    # Alternative high-quality model (for better accuracy)\n    EMBEDDING_MODEL_LARGE: str = \"sentence-transformers/all-mpnet-base-v2\"\n    \n    # Embedding cache (helps M4's unified memory)\n    ENABLE_EMBEDDING_CACHE: bool = True\n    EMBEDDING_CACHE_SIZE: int = 10000  # Number of embeddings to cache\n    EMBEDDING_CACHE_TTL: int = 3600  # 1 hour\n    \n    # ============================================================\n    # M4 PARALLEL PROCESSING\n    # ============================================================\n    # M4 has 10 cores - optimize threading\n    NUM_WORKERS: int = 10  # Match M4 core count\n    NUM_THREADS: int = 10  # Parallel processing threads\n    USE_MULTIPROCESSING: bool = True  # Enable multiprocessing\n    CHUNK_SIZE: int = 50  # Process claims in chunks for M4\n    \n    # ============================================================\n    # API CONFIGURATION\n    # ============================================================\n    WIKIPEDIA_API_TIMEOUT: int = 8  # M4 is fast, shorter timeout acceptable\n    WIKIDATA_API_TIMEOUT: int = 8\n    GITHUB_API_TIMEOUT: int = 8\n    PUBMED_API_TIMEOUT: int = 8\n    \n    # Async API calls (utilize M4's cores)\n    ENABLE_ASYNC_API: bool = True\n    MAX_CONCURRENT_API_CALLS: int = 10  # Match core count\n    API_RETRY_ATTEMPTS: int = 3\n    API_RETRY_DELAY: float = 0.5\n    \n    # ============================================================\n    # DETECTION CONFIGURATION\n    # ============================================================\n    SEMANTIC_SIMILARITY_THRESHOLD: float = 0.75\n    CONTRADICTION_THRESHOLD: float = 0.85\n    CONFIDENCE_THRESHOLD: float = 0.7\n    MAX_CLAIMS_PER_TEXT: int = 100  # M4 can handle more claims\n    \n    # Enable all detection methods for M4's power\n    ENABLE_SEMANTIC_DETECTION: bool = True\n    ENABLE_CONTRADICTION_DETECTION: bool = True\n    ENABLE_FACT_CHECKING: bool = True\n    ENABLE_DOMAIN_DETECTION: bool = True\n    \n    # ============================================================\n    # VERIFICATION CONFIGURATION\n    # ============================================================\n    ENABLE_WIKIPEDIA_VERIFICATION: bool = True\n    ENABLE_API_VERIFICATION: bool = True\n    ENABLE_SEMANTIC_VERIFICATION: bool = True\n    ENABLE_KB_VERIFICATION: bool = True\n    \n    VERIFICATION_TIMEOUT: int = 30\n    MAX_SOURCES_PER_CLAIM: int = 5\n    \n    # M4 optimization: parallel verification\n    ENABLE_PARALLEL_VERIFICATION: bool = True\n    VERIFICATION_PARALLELISM: int = 10  # Parallel verification tasks\n    \n    # ============================================================\n    # SCORING CONFIGURATION\n    # ============================================================\n    ENABLE_CONFIDENCE_SCORING: bool = True\n    ENABLE_SEVERITY_SCORING: bool = True\n    ENABLE_RISK_ASSESSMENT: bool = True\n    \n    # Use all scoring factors for M4's computational power\n    SCORING_PRECISION: float = 0.01  # More precise scoring\n    \n    # ============================================================\n    # DOMAIN CONFIGURATION\n    # ============================================================\n    ENABLED_DOMAINS: List[str] = [\n        \"general\",\n        \"code\",\n        \"medical\",\n        \"legal\",\n        \"technical\"\n    ]\n    \n    # M4 can handle all domains simultaneously\n    ENABLE_MULTI_DOMAIN_PROCESSING: bool = True\n    \n    # ============================================================\n    # CACHING & PERFORMANCE\n    # ============================================================\n    ENABLE_CACHING: bool = True\n    ENABLE_EMBEDDING_CACHE: bool = True\n    ENABLE_API_RESPONSE_CACHE: bool = True\n    ENABLE_RESULT_CACHE: bool = True\n    \n    CACHE_TTL: int = 3600  # 1 hour\n    CACHE_MAX_SIZE_MB: int = 500  # M4 has plenty of memory\n    \n    # Use persistent caching for repeated operations\n    PERSISTENT_CACHE: bool = True\n    PERSISTENT_CACHE_DIR: str = str(PROJECT_ROOT / \"data\" / \"cache\")\n    \n    # ============================================================\n    # LOGGING\n    # ============================================================\n    LOG_LEVEL: str = \"INFO\"\n    LOG_FILE: str = \"hallucination_detector_m4.log\"\n    ENABLE_DEBUG_LOGGING: bool = False  # Set to True for debugging\n    LOG_PERFORMANCE_METRICS: bool = True  # Log timing information\n    \n    # ============================================================\n    # BATCH PROCESSING OPTIMIZATION\n    # ============================================================\n    BATCH_MODE: bool = True\n    BATCH_SIZE: int = 32  # Optimized for M4 GPU\n    ENABLE_BATCH_OPTIMIZATION: bool = True\n    \n    # ============================================================\n    # MEMORY OPTIMIZATION FOR M4\n    # ============================================================\n    # M4 uses unified memory - optimize accordingly\n    OPTIMIZE_FOR_UNIFIED_MEMORY: bool = True\n    MEMORY_PRESSURE_THRESHOLD: float = 0.85  # Alert if using >85% memory\n    AUTO_OPTIMIZE_BATCH_SIZE: bool = True  # Automatically adjust batch size\n    \n    # ============================================================\n    # M4 SPECIFIC SETTINGS\n    # ============================================================\n    M4_ENABLE_NEURAL_ENGINE: bool = True  # Use M4 Neural Engine if available\n    M4_ENABLE_MEDIA_ACCELERATORS: bool = True  # Use specialized media engines\n    M4_CPU_EFFICIENCY_CORES: int = 4  # M4 has efficiency cores\n    M4_CPU_PERFORMANCE_CORES: int = 6  # M4 has performance cores\n    \n    # ============================================================\n    # PERFORMANCE MONITORING\n    # ============================================================\n    ENABLE_PERFORMANCE_MONITORING: bool = True\n    PERFORMANCE_LOG_INTERVAL: int = 100  # Log stats every 100 operations\n    TRACK_GPU_UTILIZATION: bool = True\n    TRACK_MEMORY_USAGE: bool = True\n    TRACK_CPU_USAGE: bool = True\n    \n    class Config:\n        env_file = \".env\"\n        case_sensitive = False\n\n\n# ============================================================\n# PERFORMANCE PROFILES\n# ============================================================\n\nPERFORMANCE_PROFILES = {\n    \"balance\": {\n        \"description\": \"Balanced performance and accuracy (default)\",\n        \"batch_size\": 32,\n        \"use_gpu\": True,\n        \"max_workers\": 10,\n        \"enable_caching\": True,\n    },\n    \"speed\": {\n        \"description\": \"Maximum speed, some accuracy trade-off\",\n        \"batch_size\": 64,\n        \"use_gpu\": True,\n        \"max_workers\": 10,\n        \"enable_caching\": True,\n        \"semantic_similarity_threshold\": 0.80,\n    },\n    \"accuracy\": {\n        \"description\": \"Maximum accuracy, slower processing\",\n        \"batch_size\": 16,\n        \"use_gpu\": True,\n        \"max_workers\": 5,\n        \"enable_caching\": True,\n        \"semantic_similarity_threshold\": 0.70,\n    },\n    \"memory_efficient\": {\n        \"description\": \"Memory-efficient mode\",\n        \"batch_size\": 8,\n        \"use_gpu\": True,\n        \"max_workers\": 2,\n        \"enable_caching\": False,\n    },\n}\n\n\n# ============================================================\n# INITIALIZATION\n# ============================================================\n\nm4_settings = M4Settings()\n\n\ndef get_m4_settings() -> M4Settings:\n    \"\"\"Get M4-optimized settings.\"\"\"\n    return m4_settings\n\n\ndef set_performance_profile(profile: str) -> None:\n    \"\"\"\n    Set performance profile for M4.\n    \n    Profiles:\n    - 'balance': Default balanced mode\n    - 'speed': Maximum speed\n    - 'accuracy': Maximum accuracy\n    - 'memory_efficient': Memory-conservative mode\n    \"\"\"\n    if profile not in PERFORMANCE_PROFILES:\n        raise ValueError(f\"Unknown profile: {profile}. Available: {list(PERFORMANCE_PROFILES.keys())}\")\n    \n    profile_config = PERFORMANCE_PROFILES[profile]\n    print(f\"\\n🍎 Setting M4 profile: {profile}\")\n    print(f\"   {profile_config['description']}\")\n    \n    # Apply profile settings\n    for key, value in profile_config.items():\n        if key != \"description\" and hasattr(m4_settings, key.upper()):\n            setattr(m4_settings, key.upper(), value)\n\n\n# ============================================================\n# USAGE\n# ============================================================\n\nif __name__ == \"__main__\":\n    settings = get_m4_settings()\n    \n    print(\"\\n\" + \"=\"*60)\n    print(\"🍎 Mac Air M4 Optimization Settings\")\n    print(\"=\"*60)\n    \n    print(f\"\\n✅ Device: {settings.DEVICE}\")\n    print(f\"✅ Embedding Model: {settings.EMBEDDING_MODEL}\")\n    print(f\"✅ Workers/Threads: {settings.NUM_WORKERS}\")\n    print(f\"✅ GPU Batch Size: {settings.GPU_BATCH_SIZE}\")\n    print(f\"✅ Async API Calls: {settings.ENABLE_ASYNC_API}\")\n    print(f\"✅ Parallel Verification: {settings.ENABLE_PARALLEL_VERIFICATION}\")\n    print(f\"✅ Caching Enabled: {settings.ENABLE_CACHING}\")\n    print(f\"✅ Performance Monitoring: {settings.ENABLE_PERFORMANCE_MONITORING}\")\n    \n    print(\"\\n🚀 M4 Optimization Active!\")\n    print(\"=\"*60 + \"\\n\")\n"